def prod_signs(arr):
    if not arr:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        sign = -1 if num < 0 else (1 if num > 0 else 0)

        if sign == 0:
            return 0

        product_of_signs *= sign
        sum_of_magnitudes += abs(num)

    return sum_of_magnitudes * product_of_signs

def minPath(grid, k):
    N = len(grid)
    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    best_path = None

    def dfs(r, c, current_len, path):
        nonlocal best_path

        # If we have reached the required length k
        if current_len == k:
            if best_path is None or path < best_path:
                best_path = list(path)
            return

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check boundaries
            if 0 <= nr < N and 0 <= nc < N:
                new_val = grid[nr][nc]
                path.append(new_val)

                dfs(nr, nc, current_len + 1, path)

                path.pop()

    # Try starting from every cell in the grid
    for r in range(N):
        for c in range(N):
            start_val = grid[r][c]
            dfs(r, c, 0, [start_val])

    return best_path

def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if len(stack) > 1 and stack[-2] == '[':
                return True
            if not stack or stack[-1] != '[':
                return False
            else:
                stack.pop()
    return False

