        if isinstance(val, (int, float)):
            return val, type(val)
        s = str(val).replace(',', '.')
        try:
            num = float(s)
            # Determine original format for string output
            orig_type = None
            if ',' in val and '.' not in val:
                orig_type = 'comma_str'
            elif '.' in val:
                orig_type = 'dot_str'
            else:
                orig_type = 'int_str'
            return num, orig_type
        except ValueError:
            # Should not happen based on problem description but handle safely
            return None, None

    parsed_a, type_a = parse(a)
    parsed_b, type_b = parse(b)

    if parsed_a is None or parsed_b is None:
